spec.expr:
(
  storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"} 
  / ignoring(storage_provisioning_state) 
  storage_limit_bytes{host_name="$host_name", storage_type="pool"}
) 
- 
(
  storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"} offset $__range
  / ignoring(storage_provisioning_state) 
  storage_limit_bytes{host_name="$host_name", storage_type="pool"} offset $__range
  or vector(0)
)

100 * storage_provisioning_bytes{
  host_name="$host_name",
  storage_type="pool",
  storage_provisioning_state="subscribed"
}
/
ignoring(storage_provisioning_state)
storage_limit_bytes{
   host_name="$host_name",
   storage_type="pool"
}

storage_usage_bytes{
  host_name="$host_name",
  storage_type="pool",
  storage_provisioning_state="used"
}
/
ignoring(storage_provisioning_state)
storage_limit_bytes{
  host_name="$host_name",
  storage_type="pool"
}

storage_provisioning_bytes{
  host_name="$host_name",
  storage_type="pool",
  storage_provisioning_state="subscribed"
}
/
ignoring(storage_provisioning_state)
storage_limit_bytes{
   host_name="$host_name",
   storage_type="pool"
}

(
  (
    storage_limit_bytes{host_name="$host_name", storage_type="pool"}
    - ignoring(storage_provisioning_state)
    storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"}
  )
  / ignoring(storage_provisioning_state)
  deriv(
    storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"}[$__range]
  )
) > 0

count by (state) (
  label_replace(
    (
      sum by (id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    )
    unless on (id)
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_type="volume",
      storage_consumer_state="unmapped"
    },
    "state", "Mapped & Active", "", ""
  )
)
or
label_replace(vector(0), "state", "Mapped & Active", "__name__", ".*")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_type="volume",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    ),
    "state", "Mapped & Active", "", ""
  )
)

count by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_type="volume",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    unless on (host_name, id)
    (
      storage_usage_bytes{
        host_name=~"$host_name",
        storage_type="volume",
        storage_consumer_state="mapped",
        storage_provisioning_state="used"
      }
      and on (host_name, id)
      (
        sum by (host_name, id) (
          rate(
            storage_operations_total{
              host_name=~"$host_name",
              storage_type="volume",
              storage_io_direction=~"read|write"
            }[$__range]
          )
        ) > 0.001
      )
    ),
    "state", "Mapped & Inactive", "", ""
  )
) or label_replace(vector(0), "state", "Mapped & Inactive", "", "")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_type="volume",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    ),
    "state", "Mapped & Inactive", "", ""
  )
)

label_replace(
  count(
    sum by (id) (
      storage_usage_bytes{
        host_name=~"$host_name",
        storage_consumer_state="unmapped",
        storage_type="volume"
      }
    )
  ),
  "state", "Unmapped", "", ""
)
or label_replace(vector(0), "state", "Unmapped", "", "")

label_replace(
  sum(
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_consumer_state="unmapped",
      storage_type="volume",
      storage_provisioning_state="used"
    }
  ),
  "state", "Unmapped", "", ""
)
or
label_replace(vector(0), "state", "Unmapped", "", "")

count by (state) (
  label_replace(
    (
      sum by (id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    )
    unless on (id)
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="lun",
      storage_consumer_state="unmapped"
    },
    "state", "Mapped & Active", "", ""
  )
)
or
label_replace(vector(0), "state", "Mapped & Active", "__name__", ".*")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="lun",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    ),
    "state", "Mapped & Active", "", ""
  )
)

count by (state) (
  label_replace(
    (
      sum by (id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    )
    unless on (id)
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="lun",
      storage_consumer_state="unmapped"
    },
    "state", "Mapped & Inactive", "", ""
  )
) or label_replace(vector(0), "state", "Mapped & Inactive", "", "")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="lun",
      storage_consumer_state="mapped",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    ),
    "state", "Mapped & Inactive", "", ""
  )
)

label_replace(
  count(
    sum by (id) (
      storage_usage_bytes{
        host_name=~"$host_name",
        storage_consumer_state="unmapped",
        netapp_storage_type="lun"
      }
    )
  ),
  "state", "Unmapped", "", ""
)
or label_replace(vector(0), "state", "Unmapped", "", "")

label_replace(
  sum(
    storage_usage_bytes{
      host_name=~"$host_name",
      storage_consumer_state="unmapped",
      netapp_storage_type="lun",
      storage_provisioning_state="used"
    }
  ),
  "state", "Unmapped", "", ""
)
or
label_replace(vector(0), "state", "Unmapped", "", "")

# Total capacity of unmapped and inactive LUNs
sum(
  storage_usage_bytes{
    host_name=~"$host_name",
    netapp_storage_type="lun",
    storage_consumer_state="unmapped",
    storage_provisioning_state="used"
  }
  or
  (
    (
      storage_usage_bytes{
        host_name=~"$host_name",
        netapp_storage_type="lun",
        storage_provisioning_state="used"
      }
      unless on (host_name, id)
      storage_usage_bytes{
        host_name=~"$host_name",
        netapp_storage_type="lun",
        storage_consumer_state="unmapped",
        storage_provisioning_state="used"
      }
    )
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="lun",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    )
  )
) or vector(0)

# Failed Capacity
sum(
  storage_usage_bytes{
    host_name=~"$host_name",
    netapp_storage_type="lun",
    storage_consumer_state="mapped",
    storage_provisioning_state="used"
  }
  and on (host_name, id)
  storage_status{
    host_name=~"$host_name",
    netapp_storage_type="lun",
    state=~"failed"
  } > 0
) or vector(0)

count by (state) (
  label_replace(
    (
      sum by (id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    ),
    "state", "Active", "", ""
  )
)
or
label_replace(vector(0), "state", "Active", "__name__", ".*")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="volume",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) > 0.001
    ),
    "state", "Active", "", ""
  )
)

count by (state) (
  label_replace(
    (
      sum by (id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    ),
    "state", "Inactive", "", ""
  )
)
or
label_replace(vector(0), "state", "Inactive", "__name__", ".*")

sum by (state) (
  label_replace(
    storage_usage_bytes{
      host_name=~"$host_name",
      netapp_storage_type="volume",
      storage_provisioning_state="used"
    }
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            netapp_storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    ),
    "state", "Inactive", "", ""
  )
)

(
  storage_usage_bytes{
    host_name="$host_name",
    storage_type="storage_system",
    storage_provisioning_state="free"
  }
  / ignoring(storage_provisioning_state)
  deriv(
    storage_usage_bytes{
      host_name="$host_name",
      storage_type="storage_system",
      storage_provisioning_state="used"
    }[$__range]
  )
) > 0

(
  storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"} 
  / ignoring(storage_provisioning_state) 
  storage_limit_bytes{host_name="$host_name", storage_type="pool"}
) 
- 
(
  storage_usage_bytes{host_name="$host_name", storage_type="pool", storage_provisioning_state="used"} offset $__range
  / ignoring(storage_provisioning_state) 
  storage_limit_bytes{host_name="$host_name", storage_type="pool"} offset $__range
  or vector(0)
)

storage_provisioning_bytes{
  host_name="$host_name",
  storage_type="pool",
  storage_provisioning_state="subscribed"
}
/
ignoring(storage_provisioning_state)
storage_provisioning_bytes{
  host_name="$host_name",
  storage_type="pool",
  storage_provisioning_state="configured"
}

(
  sum by (site, storage_io_direction) (
    rate(storage_operation_time_seconds_total{host_name="$host_name", storage_type="storage_system"}[5m])
  ) / 
  clamp_min( # to make sure we don't divide by if no activity
    sum by (site, storage_io_direction) (
      rate(storage_operations_total{host_name="$host_name", storage_type="storage_system"}[5m])
    ), 
    0.0001
  )
)
and # Make sure there are some operations
(
  sum by (site, storage_io_direction) (
    rate(storage_operations_total{host_name="$host_name", storage_type="storage_system"}[5m])
  ) >= 1
)

(
  sum by (site) (
    rate(storage_operation_time_seconds_total{host_name="$host_name", storage_type="storage_system"}[5m])
  ) / 
  clamp_min(
    sum by (site) (
      rate(storage_operations_total{host_name="$host_name", storage_type="storage_system"}[5m])
    ), 
    0.0001
  )
)

clamp_min(
  predict_linear(
    storage_usage_bytes{
      host_name="$host_name",
      storage_type="storage_system",
      storage_provisioning_state="used"
    }[$__range],
    7 * 24 * 3600
  ),
  0
)

clamp_min(
  predict_linear(
    storage_usage_bytes{
      host_name="$host_name",
      storage_type="storage_system",
      storage_provisioning_state="used"
    }[$__range],
    30 * 24 * 3600
  ),
  0
)

clamp_min(
  predict_linear(
    storage_usage_bytes{
      host_name="$host_name",
      storage_type="storage_system",
      storage_provisioning_state="used"
    }[$__range],
    365 * 24 * 3600
  ),
  0
)

count(
  count by (storage_consumer_name) (
    storage_limit_bytes{
      host_name=~"$host_name",
      storage_type="volume",
      storage_consumer_name!=""
    }
  )
)

# Total capacity of unmapped and inactive volumes
sum(
  storage_usage_bytes{
    host_name=~"$host_name",
    storage_type="volume",
    storage_consumer_state="unmapped",
    storage_provisioning_state="used"
  }
  or
  (
    (
      storage_usage_bytes{
        host_name=~"$host_name",
        storage_type="volume",
        storage_provisioning_state="used"
      }
      unless on (host_name, id)
      storage_usage_bytes{
        host_name=~"$host_name",
        storage_type="volume",
        storage_consumer_state="unmapped",
        storage_provisioning_state="used"
      }
    )
    and on (host_name, id)
    (
      sum by (host_name, id) (
        rate(
          storage_operations_total{
            host_name=~"$host_name",
            storage_type="volume",
            storage_io_direction=~"read|write"
          }[$__range]
        )
      ) <= 0.001
    )
  )
) or vector(0)

# Failed Capacity
sum(
  storage_usage_bytes{
    host_name=~"$host_name",
    storage_type="volume",
    storage_consumer_state="mapped",
    storage_provisioning_state="used"
  }
  and on (host_name, id)
  storage_status{
    host_name=~"$host_name",
    storage_type="volume",
    state=~"failed"
  } > 0
) or vector(0)
